import{_ as a,c as t,o as n,ag as o}from"./chunks/framework.CQuhCYrb.js";const b=JSON.parse('{"title":"Notes","description":"","frontmatter":{"title":"Notes"},"headers":[],"relativePath":"general/notes.md","filePath":"general/notes.md","lastUpdated":null}'),r={name:"general/notes.md"};function i(s,e,l,d,g,c){return n(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h1><h2 id="effective-note-taking-and-research-management" tabindex="-1">Effective Note-Taking and Research Management <a class="header-anchor" href="#effective-note-taking-and-research-management" aria-label="Permalink to &quot;Effective Note-Taking and Research Management&quot;">​</a></h2><p>Return to <a href="/research/">Go to Citations</a></p><p>Welcome to this community guide on efficient note-taking and research management tailored for academic researchers and OSINT professionals.</p><h3 id="zotero-and-obsidian-advanced-tools-for-research-management" tabindex="-1">Zotero and Obsidian: Advanced Tools for Research Management <a class="header-anchor" href="#zotero-and-obsidian-advanced-tools-for-research-management" aria-label="Permalink to &quot;Zotero and Obsidian: Advanced Tools for Research Management&quot;">​</a></h3><h3 id="what-are-zotero-and-obsidian" tabindex="-1">What are Zotero and Obsidian? <a class="header-anchor" href="#what-are-zotero-and-obsidian" aria-label="Permalink to &quot;What are Zotero and Obsidian?&quot;">​</a></h3><ul><li><p><strong>Zotero</strong> is a robust reference management software that excels in organizing research materials, annotating PDFs, and integrating with word processors for streamlined citation management.</p><ul><li>**Key Features&#39;&#39;&#39;: <em>&#39;</em> Bibliographic data management. <em>&#39;</em> Direct PDF annotation and note linkage. <em>&#39;</em> Seamless word processor integration for citations.</li></ul></li><li><p><strong>Obsidian</strong> is a markdown-based knowledge management tool ideal for creating a linked database of notes, enhancing research organization through its advanced linking capabilities.</p><ul><li>**Key Features&#39;&#39;&#39;: <em>&#39;</em> Bidirectional links for connected thinking. <em>&#39;</em> Graph views for visual mapping of notes. <em>&#39;</em> Extensive plugin support for customized functionality.</li></ul></li></ul><h3 id="setting-up-zotero-and-obsidian" tabindex="-1">Setting Up Zotero and Obsidian <a class="header-anchor" href="#setting-up-zotero-and-obsidian" aria-label="Permalink to &quot;Setting Up Zotero and Obsidian&quot;">​</a></h3><h4 id="installing-the-tools" tabindex="-1">Installing the Tools <a class="header-anchor" href="#installing-the-tools" aria-label="Permalink to &quot;Installing the Tools&quot;">​</a></h4><ol><li><p><strong>Zotero</strong>: <a href="https://www.zotero.org/download/" target="_blank" rel="noreferrer">Download here</a></p></li><li><p><strong>Obsidian</strong>: <a href="https://obsidian.md/download" target="_blank" rel="noreferrer">Download here</a></p></li><li><p><strong>Browser plugins for Zotero</strong>: For capturing online references directly into Zotero.</p></li></ol><h4 id="integrating-zotero-with-obsidian" tabindex="-1">Integrating Zotero with Obsidian <a class="header-anchor" href="#integrating-zotero-with-obsidian" aria-label="Permalink to &quot;Integrating Zotero with Obsidian&quot;">​</a></h4><ul><li><p>Utilize the <strong>Zotero-Obsidian Integration</strong> plugin to seamlessly sync references into Obsidian notes.</p></li><li><p><strong>Setup Guide</strong>: <a href="https://github.com/argenos/zotero-mdnotes" target="_blank" rel="noreferrer">Zotero-Obsidian Integration</a></p></li></ul><h3 id="using-zotero-and-obsidian-together" tabindex="-1">Using Zotero and Obsidian Together <a class="header-anchor" href="#using-zotero-and-obsidian-together" aria-label="Permalink to &quot;Using Zotero and Obsidian Together&quot;">​</a></h3><h4 id="managing-references-with-zotero" tabindex="-1">Managing References with Zotero <a class="header-anchor" href="#managing-references-with-zotero" aria-label="Permalink to &quot;Managing References with Zotero&quot;">​</a></h4><ul><li><p><strong>Organize Research</strong>: Create structured collections for different research topics or projects.</p></li><li><p><strong>Capture References</strong>: Add references via Zotero’s browser extension; attach PDFs and annotate them directly within Zotero.</p></li></ul><h4 id="taking-notes-in-obsidian" tabindex="-1">Taking Notes in Obsidian <a class="header-anchor" href="#taking-notes-in-obsidian" aria-label="Permalink to &quot;Taking Notes in Obsidian&quot;">​</a></h4><ul><li><p><strong>Create a Vault</strong>: Designate a vault in Obsidian for each research project for better organization.</p></li><li><p><strong>Link Notes to References</strong>: Embed Zotero citations in Obsidian to create a richly linked research database.</p></li><li><p><strong>Graph View</strong>: Use Obsidian’s graph view to visualize and navigate the interconnections between notes.</p></li></ul><h3 id="workflow-example" tabindex="-1">Workflow Example <a class="header-anchor" href="#workflow-example" aria-label="Permalink to &quot;Workflow Example&quot;">​</a></h3><ol><li><p><strong>Research Phase</strong>: Collect and annotate articles in Zotero.</p></li><li><p><strong>Synthesis Phase</strong>: Synthesize insights in Obsidian, linking back to Zotero references.</p></li><li><p><strong>Writing Phase</strong>: Utilize Obsidian to draft manuscripts or reports with integrated citations from Zotero.</p></li></ol><h3 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h3><ul><li><p><strong>Data Backup</strong>: Regularly back up Zotero libraries and Obsidian vaults.</p></li><li><p><strong>Organization</strong>: Use tags in Obsidian and collections in Zotero for meticulous organization.</p></li><li><p><strong>Regular Reviews</strong>: Periodically review the notes and references to keep the database current and relevant.</p></li></ul><h3 id="onenote-and-zbib-for-government-approved-research-environments" tabindex="-1">OneNote and Zbib for Government-Approved Research Environments <a class="header-anchor" href="#onenote-and-zbib-for-government-approved-research-environments" aria-label="Permalink to &quot;OneNote and Zbib for Government-Approved Research Environments&quot;">​</a></h3><p>In settings where software installation is restricted, combining Microsoft OneNote with Zbib can offer an alternative solution.</p><ul><li><p><strong>OneNote</strong>: Leverage OneNote for note-taking available on government computers.</p></li><li><p><strong>Zbib</strong>: Use <a href="https://zbib.org" target="_blank" rel="noreferrer">Zbib</a>, an online tool for quick bibliographic reference management.</p></li></ul><h3 id="integrating-onenote-with-zbib" tabindex="-1">Integrating OneNote with Zbib <a class="header-anchor" href="#integrating-onenote-with-zbib" aria-label="Permalink to &quot;Integrating OneNote with Zbib&quot;">​</a></h3><ul><li><p><strong>Collect References</strong>: Use Zbib to manage and export citations.</p></li><li><p><strong>Note Organization in OneNote</strong>: Organize notes by projects or topics, linking back to Zbib references as needed.</p></li></ul><h3 id="best-practices-for-onenote-and-zbib" tabindex="-1">Best Practices for OneNote and Zbib <a class="header-anchor" href="#best-practices-for-onenote-and-zbib" aria-label="Permalink to &quot;Best Practices for OneNote and Zbib&quot;">​</a></h3><ul><li><p><strong>Regular Backups</strong>: Ensure notes and references are backed up in cloud storage.</p></li><li><p><strong>Efficient Tagging</strong>: Use OneNote’s tagging system to categorize and retrieve content easily.</p></li><li><p><strong>Review and Update</strong>: Keep the research materials reviewed and updated regularly to reflect the latest findings and insights.</p></li></ul><h3 id="additional-resources" tabindex="-1">Additional Resources <a class="header-anchor" href="#additional-resources" aria-label="Permalink to &quot;Additional Resources&quot;">​</a></h3><ul><li><p><a href="https://www.zotero.org/support/" target="_blank" rel="noreferrer">Zotero Documentation</a></p></li><li><p><a href="https://forum.obsidian.md/" target="_blank" rel="noreferrer">Obsidian Forum</a></p></li><li><p><a href="https://medium.com/@farallon/uncommon-osint-obsidian-semantic-meaning-and-nlp-3339e1e51d70" target="_blank" rel="noreferrer">Guide on Academic Workflow with Zotero and Obsidian</a></p></li></ul>',30)])])}const p=a(r,[["render",i]]);export{b as __pageData,p as default};
